begin;
with target as (select id from public.workspaces where name='Ball Pit Motorsports' order by created_at limit 1),
src as (select * from jsonb_to_recordset('[{"business_id":"VEH-001","name":"Golf Ball","status":"active","year":2011,"make":"Porsche","model":"Cayman 987.2 Base","trim":"Time Trial / Track Car","description":"Salvage-title, hail-damaged base Cayman; dedicated time-trial platform; AIM MXL2 and SmartyCam\n\nNitron R1 coilovers; Tarrett GT3 front and Cayman R rear sway bars; Competition Motorsports half cage; Sparco seats/harnesses; GT3 brake master cylinder and ducts; CSF three-radiator cooling; Fabspeed headers; Soul race exhaust; Softronic tune; Numeric shifter; solid mounts; Apex wheels\n\nPrimary Ball Pit performance car; future wheel-to-wheel conversion planned"},{"business_id":"VEH-002","name":"Cheese Ball","status":"active","year":1994,"make":"Mazda","model":"MX-5 Miata NA Spec Miata","trim":"Spec Miata / Rental Race Car","description":"Yellow 1.8L Spec Miata prepared for wheel-to-wheel competition\n\nSpec Miata safety and race preparation; current setup to be refined after race-school update\n\nAvailable through Ball Pit for approved ECR member/race-school use; current build details remain in progress"},{"business_id":"VEH-003","name":"Low Ball","status":"active","year":2008,"make":"Mazda","model":"Mazdaspeed3","trim":"Rally / Dirt Car","description":"143,000-mile body; approximately 108,000-mile swapped powertrain; budget rally platform\n\nYellow Speed Racing rally coilovers; upgraded motor mounts; half cage; bash bar; off-road lights; Enkei RPF1 17x9 wheels; Cobb intake, exhaust, HPFP internals, Accessport Stage 2 tune and brake upgrades; CorkSport shifter components\n\nECR rally-track rental only for members or select event days"},{"business_id":"VEH-004","name":"Meat Ball","status":"active","year":2024,"make":"Toyota","model":"Tundra","trim":"Tow Vehicle","description":"Modified tow vehicle used to haul the Ball Pit fleet and Ball Caddy\n\nLight off-road and towing modifications; detailed build list to be documented\n\nFamily Ball; not a rental"},{"business_id":"VEH-005","name":"Ball Caddy","status":"active","year":2024,"make":"Car Hauler","model":"18-foot open car hauler","trim":"Track Support Trailer","description":"18-foot open car hauler configured for transport and trackside support\n\nElectric winch with dedicated battery; inverter and power station; 100 PSI onboard air; 2,500W inverter generator\n\nSupport asset rather than a self-propelled vehicle; year and manufacturer not yet documented"},{"business_id":"VEH-006","name":"Snow Ball","status":"active","year":1998,"make":"Honda","model":"Civic Type R EK9","trim":"Personal / Show Car","description":"JDM-import EK9 Civic Type R; original B16B; Cars and Coffee / personal-use car\n\nPreservation-focused personal car; detailed modification list not yet documented\n\nFamily Ball; not for rent"},{"business_id":"VEH-007","name":"The First Ball","status":"sold","year":2020,"make":"Mazda","model":"MX-5 Miata ND2","trim":"Former Track Car","description":"Rebuilt-title Club/Brembo-BBS-Recaro package; Roshan''s first track car and entry into motorsports\n\nXida Race coilovers; Progress sway bars; Karcepts camber bushings; ST42 front brakes; RoadsterSport header; Cobalt exhaust; Mishimoto oil cooler; Fab9 tune; AWR engine mounts; Blackbird roll bar; Buddy Club seats; Sparco six-point harness; Race Louvers hood vent\n\nSold to Jose in September 2025; remains part of the Ball Pit story"},{"business_id":"VEH-008","name":"Blue Ball","status":"sold","year":2021,"make":"Can-Am","model":"Maverick X3 X RS","trim":"Former Off-Road / Short-Course Car","description":"Short-course side-by-side that introduced Ball Pit to dirt driving and jumping\n\nS3 cage; Maxxis Liberty tires; Raceline wheels; Sparco Evo L seats; six-point harnesses; window net; fire extinguisher; short-course shock build; quick-release steering; AIM belt-temperature monitor; Wilwood master cylinder; upgraded radiator; full wrap\n\nSold February 2026; legacy off-road platform"}]'::jsonb) as x(business_id text,name text,status text,year integer,make text,model text,trim text,description text))
update public.vehicles v set business_id=s.business_id,status=s.status,year=s.year,make=s.make,model=s.model,trim=s.trim,description=s.description
from src s,target w where v.workspace_id=w.id and v.name=s.name;
with target as (select id from public.workspaces where name='Ball Pit Motorsports' order by created_at limit 1),
