xt,status text,year integer,make text,model text,trim text,description text))
insert into public.vehicles(workspace_id,business_id,name,status,year,make,model,trim,description)
select w.id,s.business_id,s.name,s.status,s.year,s.make,s.model,s.trim,s.description from src s cross join target w
where not exists(select 1 from public.vehicles v where v.workspace_id=w.id and v.name=s.name);
with target as (select id from public.workspaces where name='Ball Pit Motorsports' order by created_at limit 1),
src as (select * from jsonb_to_recordset('[{"name":"Eagles Canyon Raceway","address":"7629 North FM 51, Decatur, TX 76234","notes":"Decatur Municipal Airport (KLUD — METAR/AWOS)"},{"name":"ECR SHORT","address":"7629 North FM 51, Decatur, TX 76234","notes":"Decatur Municipal Airport (KLUD — METAR/AWOS)"},{"name":"Motorsport Ranch","address":"9012 Performance Court, Cresson, TX 76035","notes":"Granbury Regional Airport (KGDJ — METAR/AWOS)"},{"name":"G2 MOTORSPORT PARK","address":"1001 County Road 526, Anna, TX 75409","notes":"McKinney National Airport (KTKI — METAR/ASOS)"},{"name":"Hallett Motor Racing Circuit","address":"59901 E. 5500 Road, Jennings, OK 74038","notes":"Cushing Municipal Airport (KCUH — METAR/AWOS)"},{"name":"Circuit of the Americas","address":"9201 Circuit of the Americas Blvd., Austin, TX 78617","notes":"Austin-Bergstrom International Airport (KAUS — METAR/ASOS)"}]'::jsonb) as x(name text,address text,notes text))
update public.tracks t set address=coalesce(s.address,t.address),notes=coalesce(s.notes,t.notes) from src s,target w where t.workspace_id=w.id and t.name=s.name;
