insert into public.track_configurations(workspace_id,track_id,name)
select w.id,t.id,s.configuration_name from src s cross join target w join public.tracks t on t.workspace_id=w.id and t.name=s.track_name
where s.configuration_name is not null on conflict(track_id,name) do nothing;
