insert into public.tire_sets(workspace_id,vehicle_id,business_id,manufacturer,model,size,purchased_on,first_used_on,starting_sessions,status,notes)
select w.id,v.id,s.business_id,s.manufacturer,s.model,s.size,s.purchased_on,s.first_used_on,s.starting_sessions,s.status,s.notes
from src s cross join target w join public.vehicles v on v.workspace_id=w.id and v.name=s.vehicle
on conflict(workspace_id,business_id) do update set vehicle_id=excluded.vehicle_id,manufacturer=excluded.manufacturer,model=excluded.model,size=excluded.size,purchased_on=excluded.purchased_on,first_used_on=excluded.first_used_on,starting_sessions=excluded.starting_sessions,status=excluded.status,notes=excluded.notes;
