insert into public.events(workspace_id,business_id,event_date,event_name,track_name,configuration_name,organization_name,status,created_by,vehicle_id,team_name,driver_name,event_type,temperature_f,conditions,precipitation_in,wind_speed_mph,humidity_pct,track_condition,tire_set_business_id,front_pad_set_business_id,rear_pad_set_business_id,notes,track_id,configuration_id,tire_set_id,front_pad_set_id,rear_pad_set_id)
select w.id,s.business_id,s.event_date,s.event_name,s.track_name,s.configuration_name,s.organization_name,s.status,o.id,v.id,s.team_name,s.driver_name,s.event_type,s.temperature_f,s.conditions,s.precipitation_in,s.wind_speed_mph,s.humidity_pct,s.track_condition,s.tire_business_id,s.front_pad_business_id,s.rear_pad_business_id,s.notes,t.id,tc.id,ti.id,fp.id,rp.id
from src s cross join target w cross join owner o join public.vehicles v on v.workspace_id=w.id and v.name=s.vehicle join public.tracks t on t.workspace_id=w.id and t.name=s.track_name join public.track_configurations tc on tc.workspace_id=w.id and tc.track_id=t.id and tc.name=s.configuration_name
left join public.tire_sets ti on ti.workspace_id=w.id and ti.business_id=s.tire_business_id
left join public.pad_sets fp on fp.workspace_id=w.id and fp.business_id=s.front_pad_business_id
left join public.pad_sets rp on rp.workspace_id=w.id and rp.business_id=s.rear_pad_business_id
on conflict(workspace_id,business_id) do update set event_date=excluded.event_date,event_name=excluded.event_name,track_name=excluded.track_name,configuration_name=excluded.configuration_name,organization_name=excluded.organization_name,status=excluded.status,created_by=excluded.created_by,vehicle_id=excluded.vehicle_id,team_name=excluded.team_name,driver_name=excluded.driver_name,event_type=excluded.event_type,temperature_f=excluded.temperature_f,conditions=excluded.conditions,precipitation_in=excluded.precipitation_in,wind_speed_mph=excluded.wind_speed_mph,humidity_pct=excluded.humidity_pct,track_condition=excluded.track_condition,tire_set_business_id=excluded.tire_set_business_id,front_pad_set_business_id=excluded.front_pad_set_business_id,rear_pad_set_business_id=excluded.rear_pad_set_business_id,notes=excluded.notes,track_id=excluded.track_id,configuration_id=excluded.configuration_id,tire_set_id=excluded.tire_set_id,front_pad_set_id=excluded.front_pad_set_id,rear_pad_set_id=excluded.rear_pad_set_id;
