insert into public.sessions(workspace_id,event_id,session_number,best_lap_ms,is_fastest,notes,created_by)
select w.id,e.id,s.session_number,s.best_lap_ms,s.is_fastest,s.notes,o.id from src s cross join target w cross join owner o join public.events e on e.workspace_id=w.id and e.business_id=s.event_business_id
on conflict(event_id,session_number) do update set best_lap_ms=excluded.best_lap_ms,is_fastest=excluded.is_fastest,notes=excluded.notes,created_by=excluded.created_by;
with target as (select id from public.workspaces where name='Ball Pit Motorsports' order by created_at limit 1),
